namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    // In-memory ratings store: recipeId -> list of ratings
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
            new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you going" },
            new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats to end any meal" },
            new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
            new() { Name = "Drinks", Icon = "🥤", Description = "Refreshing beverages and smoothies" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend breakfast.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just blended.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown. Serve with maple syrup."],
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Description = "Crisp romaine lettuce with creamy Caesar dressing and crunchy croutons.",
                Ingredients = ["1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup parmesan cheese", "1 cup croutons", "2 anchovy fillets (optional)", "Juice of 1 lemon"],
                Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze lemon juice over the top.", "Toss gently and serve immediately."],
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and hearty Italian meat sauce over perfectly cooked pasta.",
                Ingredients = ["1 lb ground beef", "1 lb spaghetti", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic", "2 tbsp olive oil", "1 tsp oregano", "Salt and pepper to taste"],
                Steps = ["Cook spaghetti according to package directions.", "Heat olive oil in a large pan over medium heat.", "Sauté onion and garlic until softened.", "Add ground beef and cook until browned.", "Stir in crushed tomatoes, oregano, salt, and pepper.", "Simmer for 20 minutes. Serve sauce over spaghetti."],
            },
            new()
            {
                Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Chewy, gooey cookies loaded with chocolate chips.",
                Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
                Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet.", "Bake 9–11 minutes until golden. Cool on wire rack."],
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Description = "Fresh and zesty avocado dip, perfect with tortilla chips.",
                Ingredients = ["3 ripe avocados", "1 lime, juiced", "1 tsp salt", "½ cup onion, diced", "3 tbsp fresh cilantro", "2 roma tomatoes, diced", "1 tsp minced garlic", "1 pinch cayenne pepper"],
                Steps = ["Halve avocados and remove pits.", "Mash avocado flesh in a bowl.", "Stir in lime juice, salt, onion, cilantro, tomatoes, and garlic.", "Add cayenne pepper to taste.", "Refrigerate for 1 hour before serving."],
            },
            new()
            {
                Id = 6, Title = "Berry Smoothie", Category = "Drinks",
                Description = "A refreshing blend of mixed berries and yogurt.",
                Ingredients = ["1 cup mixed berries", "1 banana", "½ cup Greek yogurt", "½ cup milk", "1 tbsp honey", "Ice cubes"],
                Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into a glass and serve immediately."],
            },
            new()
            {
                Id = 7, Title = "French Toast", Category = "Breakfast",
                Description = "Golden, custardy bread slices dusted with cinnamon sugar.",
                Ingredients = ["4 thick slices bread", "2 eggs", "½ cup milk", "1 tsp cinnamon", "1 tsp vanilla extract", "Butter for cooking", "Maple syrup for serving"],
                Steps = ["Whisk eggs, milk, cinnamon, and vanilla together.", "Dip each bread slice in the egg mixture.", "Melt butter on a skillet over medium heat.", "Cook each slice 2–3 minutes per side until golden.", "Serve with maple syrup and fresh berries."],
            },
            new()
            {
                Id = 8, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "Quick and colorful chicken with crisp vegetables in a savory sauce.",
                Ingredients = ["2 chicken breasts, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic", "1 tsp ginger", "Cooked rice for serving"],
                Steps = ["Mix soy sauce, sesame oil, and cornstarch for the sauce.", "Heat oil in a wok over high heat.", "Cook chicken until no longer pink. Remove and set aside.", "Stir-fry vegetables with garlic and ginger for 3 minutes.", "Return chicken to wok and pour sauce over.", "Cook 2 more minutes until sauce thickens. Serve over rice."],
            },
        ];
        _nextId = 9;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public (double average, int count) AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5)
            throw new ArgumentOutOfRangeException(nameof(stars));

        if (!_ratings.TryGetValue(recipeId, out var ratings))
        {
            ratings = [];
            _ratings[recipeId] = ratings;
        }

        ratings.Add(stars);
        var avg = ratings.Average();
        var count = ratings.Count;

        var recipe = GetRecipeById(recipeId);
        if (recipe is not null)
        {
            recipe.AverageRating = avg;
            recipe.RatingCount = count;
        }

        return (avg, count);
    }

    public (double average, int count) GetRating(int recipeId)
    {
        if (_ratings.TryGetValue(recipeId, out var ratings) && ratings.Count > 0)
            return (ratings.Average(), ratings.Count);
        return (0, 0);
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "selected" : "") @(star <= _hoverRating ? "hover" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= (_hoverRating > 0 ? _hoverRating : _selectedRating) ? "★" : "☆")
        </span>
    }
    @if (_ratingCount > 0)
    {
        <span class="rating-info">@_averageRating.ToString("F1") avg · @_ratingCount rating@(_ratingCount != 1 ? "s" : "")</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int _selectedRating;
    private int _hoverRating;
    private double _averageRating;
    private int _ratingCount;
    private bool _submitted;

    protected override void OnInitialized()
    {
        var (avg, count) = RecipeService.GetRating(RecipeId);
        _averageRating = avg;
        _ratingCount = count;
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        var (avg, count) = RecipeService.AddRating(RecipeId, stars);
        _averageRating = avg;
        _ratingCount = count;
        _submitted = true;
    }
}

@page "/category/{CategoryName}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@_category?.Icon @CategoryName Recipes</h1>
<p class="lead">@_category?.Description</p>

<div class="row">
    @if (_recipes.Count == 0)
    {
        <p>No recipes in this category yet. <a href="/submit">Submit one!</a></p>
    }
    else
    {
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    }
</div>

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];
    private RecipeCategory? _category;

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
        _category = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <StarRating RecipeId="@_recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">👨‍🍳 Steps</h5></div>
                <ol class="list-group list-group-numbered list-group-flush">
                    @foreach (var step in _recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>

    <a href="/category/@_recipe.Category" class="btn btn-outline-secondary">← Back to @_recipe.Category</a>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="lead">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added to the @_model.Category category.</p>
        <a href="/recipe/@_submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label" for="description">Description</label>
            <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2"
                           placeholder="A brief description of the dish" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="_ingredientsText" rows="5"
                           placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="_stepsText" rows="5"
                           placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid())">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private string _ingredientsText = string.Empty;
    private string _stepsText = string.Empty;
    private bool _submitted;
    private int _submittedId;
    private List<RecipeCategory> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private bool IsValid() =>
        !string.IsNullOrWhiteSpace(_model.Title) &&
        !string.IsNullOrWhiteSpace(_model.Category) &&
        !string.IsNullOrWhiteSpace(_ingredientsText) &&
        !string.IsNullOrWhiteSpace(_stepsText);

    private void HandleSubmit()
    {
        if (!IsValid()) return;

        var recipe = new Recipe
        {
            Title = _model.Title.Trim(),
            Category = _model.Category,
            Description = _model.Description?.Trim() ?? string.Empty,
            Ingredients = _ingredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _stepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };

        RecipeService.AddRecipe(recipe);
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _ingredientsText = string.Empty;
        _stepsText = string.Empty;
        _submitted = false;
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string? Description { get; set; }
    }
}

